window.AUTH=window.AUTH||{};window.AUTH["18-1584"]={"d":"18-1584","id":"2019/18-1584","n":"United States Forest Service v. Cowpasture River Preservation Association","briefs":[{"k":"petitioner","label":"Brief of Federal Petitioners","date":"2019-12-02","url":"https://www.supremecourt.gov/DocketPDF/18/18-1584/124106/20191202153748818_18-1584%2018-1587bsUnitedStates.pdf","side":"pet","n":96},{"k":"petitioner","label":"Brief of petitioner Atlantic Coast Pipeline, LLC","date":"2019-12-02","url":"https://www.supremecourt.gov/DocketPDF/18/18-1584/124078/20191202141517431_18-1587%20Atlantic%20Coast%20Pipeline%20Opening%20Brief.pdf","side":"pet","n":57},{"k":"respondent","label":"Brief of respondents Cowpasture River Preservation Association, et al.","date":"2020-01-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-1584/128785/20200115172425857_18-1584%20-%2018-1587bs.pdf","side":"res","n":112},{"k":"reply","label":"Reply of petitioners United States Forest Service, et al.","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-1584/133073/20200214133544799_18-158418-1587rbUnitedStates.pdf","side":"pet","n":54},{"k":"reply","label":"Reply of petitioner Atlantic Coast Pipeline, LLC","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-1584/133045/20200214123212109_18-1587rb.pdf","side":"pet","n":16}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US2PP_web.pdf#page=192","tr":true,"items":[{"t":"case","label":"Butte City Water Co. v. Baker","cite":"196 U.S. 119","y":1905,"id":"scdb/1904-151","sc":1,"sum":"While the disposal of the public lands is made through the exercise of legislative power entrusted to Congress by the Constitution, yet Congress prescribing the main and substantial conditions thereof may rightfully entrust to local legislatures the determination of those minor matters as to such disposal which amount to mere regulations.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"op":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"40","1":"27"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26"}},{"t":"case","label":"Kansas v. Colorado","cite":"206 U.S. 46","y":1907,"id":"scdb/1906-063","sc":1,"ar":3,"sum":"Kansas having brought in this court an original suit to restrain Colorado and certain corporations organized under its laws from diverting the water of the Arkansas River for the irrigation of lands in Colorado, thereby, as alleged, preventing the natural and customary flow of the river into Kansas and through its territory, the United States filed an intervening petition claiming a right to control the waters of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Ohio Forestry Ass’n v. Sierra Club","cite":"523 U.S. 726","y":1998,"id":"1997/97-16","sc":1,"op":1,"ar":1,"sum":"The Court held that the controversy is not yet ripe for judicial review.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Sierra Club v. United States Dep’t of the Interior","cite":"899 F.3d 260","y":2018,"url":"https://www.courtlistener.com/c/F.3d/899/260/","by":{"0":"38","1":"13, 16","2":"10","4":"14"}},{"t":"case","label":"United States v. New Mexico","cite":"438 U.S. 696","y":1978,"id":"1977/77-510","sc":1,"sum":"The United States, in setting aside the Gila National Forest from other public lands, held to have reserved the use of water out of the Rio Mimbres only where necessary to preserve the timber in the forest or to secure favorable water flows, and hence not to have a reserved right for aesthetic, recreational, wildlife-preservation, and stockwatering purposes. That this was Congress' intent is revealed in the limited …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 20","1":"46"}},{"t":"case","label":"Whitman v. American Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"op":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"0":"40","1":"41"}},{"t":"const","label":"Article IV, Section 3, Clause 2","clauses":[["property-clause","Territory and Property Clause"]],"text":"The Congress shall have Power to dispose of and make all needful Rules and Regulations respecting the Territory or other Property belonging to the United States; and nothing in this Constitution shall be so construed as to Prejudice any Claims of the United States, or of any particular State.","by":{"0":"21"}},{"t":"usc","label":"16 U.S.C. § 472","url":"https://www.law.cornell.edu/uscode/text/16/472","op":1,"by":{"0":"2, 5, 20"}},{"t":"usc","label":"16 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/16/521","stext":{"head":"§521. Lands acquired to be reserved, held, and administered as national forest lands; designation","paras":[[0,"Subject to the provisions of section 519 of this title the lands acquired under this Act shall be permanently reserved, held, and administered as national forest lands under the provisions of section 471 1 of this title and acts supplemental to and amendatory thereof. And the Secretary of Agriculture may from time to time divide the lands acquired under this Act into such specific national forests and so designate the same as he may deem best for administrative purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/521?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§521. Lands acquired to be reserved, held, and administered as national forest lands; designation","tname":"Conservation","by":{"0":"22","1":"3, 9","2":"36, 38, 39, 40, 41","3":"8","4":"3, 11"}},{"t":"usc","label":"16 U.S.C. § 516","url":"https://www.law.cornell.edu/uscode/text/16/516","stext":{"head":"§516. Exchange of lands in the public interest; equal value; cutting and removing timber; publication of contemplated exchange","paras":[[0,"When the public interests will be benefited thereby, the Secretary of Agriculture is hereby authorized, in his discretion, to accept on behalf of the United States title to any lands within the exterior boundaries of national forests which, in his opinion, are chiefly valuable for the purposes of this Act, and in exchange therefor to convey by deed not to exceed an equal value of such national forest land in the same State, or he may authorize the grantor to cut and remove an equal value of timber within such national forests in the same State, the values in each case to be determined by him: Provided, That before any such exchange is effected notice of the contemplated exchange reciting the lands involved shall be published once each week for four successive weeks in some newspaper of general circulation in the county or counties in which may be situated the lands to be accepted, and in some like newspaper published in any county in which may be situated any lands or timber to be given in such exchange. Timber given in such exchanges shall be cut and removed under the laws and regulations relating to such national forests, and under the direction and supervision and in accordance with the requirements of the Secretary of Agriculture. Lands so accepted by the Secretary of Agriculture shall, upon acceptance, become parts of the national forests within whose exterior boundaries they are located, and be subjected to all provisions of this Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/516?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§516. Exchange of lands in the public interest; equal value; cutting and removing timber; publication of contemplated exchange","tname":"Conservation","by":{"0":"22","2":"39"}},{"t":"usc","label":"16 U.S.C. § 519","url":"https://www.law.cornell.edu/uscode/text/16/519","by":{"0":"22"}},{"t":"law","label":"Pub. L. No. 89-250","url":"https://www.govinfo.gov/link/statute/79/971","by":{"0":"23"}},{"t":"law","label":"Pub. L. No. 89-446","url":"https://www.govinfo.gov/link/statute/80/199","by":{"0":"24","1":"29"}},{"t":"law","label":"Pub. L. No. 93-153","url":"https://www.govinfo.gov/link/statute/87/577","by":{"0":"2","2":"17, 18"}},{"t":"usc","label":"43 U.S.C. § 1701","url":"https://www.law.cornell.edu/uscode/text/43/1701","by":{"0":"24"}},{"t":"usc","label":"43 U.S.C. § 1702","url":"https://www.law.cornell.edu/uscode/text/43/1702","subs":["(g)"],"by":{"0":"24, 24"}},{"t":"usc","label":"43 U.S.C. § 1714","url":"https://www.law.cornell.edu/uscode/text/43/1714","subs":["(a)"],"by":{"0":"24"}},{"t":"usc","label":"30 U.S.C. § 181","url":"https://www.law.cornell.edu/uscode/text/30/181","stext":{"head":"§181. Lands subject to disposition; persons entitled to benefits; reciprocal privileges; helium rights reserved","paras":[[0,"Deposits of coal, phosphate, sodium, potassium, oil, oil shale, gilsonite (including all vein-type solid hydrocarbons), or gas, and lands containing such deposits owned by the United States, including those in national forests, but excluding lands acquired under the Appalachian Forest Act, approved March 1, 1911 (36 Stat. 961), and those in incorporated cities, towns, and villages and in national parks and monuments, those acquired under other Acts subsequent to February 25, 1920, and lands within the naval petroleum and oil-shale reserves, except as hereinafter provided, shall be subject to disposition in the form and manner provided by this chapter to citizens of the United States, or to associations of such citizens, or to any corporation organized under the laws of the United States, or of any State or Territory thereof, or in the case of coal, oil, oil shale, or gas, to municipalities. Citizens of another country, the laws, customs, or regulations of which deny similar or like privileges to citizens or corporations of this country, shall not by stock ownership, stock holding, or stock control, own any interest in any lease acquired under the provisions of this chapter."],[0,"The term \"oil\" shall embrace all nongaseous hydrocarbon substances other than those substances leasable as coal, oil shale, or gilsonite (including all vein-type solid hydrocarbons)."],[0,"The term \"combined hydrocarbon lease\" shall refer to a lease issued in a special tar sand area pursuant to section 226 of this title after November 16, 1981."],[0,"The term \"special tar sand area\" means (1) an area designated by the Secretary of the Interior's orders of November 20, 1980 (45 FR 76800–76801) and January 21, 1981 (46 FR 6077–6078) as containing substantial deposits of tar sand."],[0,"The United States reserves the ownership of and the right to extract helium from all gas produced from lands leased or otherwise granted under the provisions of this chapter, under such rules and regulations as shall be prescribed by the Secretary of the Interior: Provided further, That in the extraction of helium from gas produced from such lands it shall be so extracted as to cause no substantial delay in the delivery of gas produced from the well to the purchaser thereof, and that extraction of helium from gas produced from such lands shall maintain the lease as if the extracted helium were oil and gas."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/30/181?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§181. Lands subject to disposition; persons entitled to benefits; reciprocal privileges; helium rights reserved","tname":"Mineral Lands and Mining","by":{"0":"2","2":"passim","3":"2"}},{"t":"usc","label":"30 U.S.C. § 185","url":"https://www.law.cornell.edu/uscode/text/30/185","subs":["(1970)","(a)","(b)(1)","(b)(3)","(c)(1)","(q)","(b)"],"stext":{"head":"§185. Rights-of-way for pipelines through Federal lands","paras":[[0,"(a) Grant of authority"],[0,"Rights-of-way through any Federal lands may be granted by the Secretary of the Interior or appropriate agency head for pipeline purposes for the transportation of oil, natural gas, synthetic liquid or gaseous fuels, or any refined product produced therefrom to any applicant possessing the qualifications provided in section 181 of this title in accordance with the provisions of this section."],[0,"(b) Definitions"],[0,"(1) For the purposes of this section \"Federal lands\" means all lands owned by the United States except lands in the National Park System, lands held in trust for an Indian or Indian tribe, and lands on the Outer Continental Shelf. A right-of-way through a Federal reservation shall not be granted if the Secretary or agency head determines that it would be inconsistent with the purposes of the reservation."],[0,"(2) \"Secretary\" means the Secretary of the Interior."],[0,"(3) \"Agency head\" means the head of any Federal department or independent Federal office or agency, other than the Secretary of the Interior, which has jurisdiction over Federal lands."],[0,"(c) Inter-agency coordination"],[0,"(1) Where the surface of all of the Federal lands involved in a proposed right-of-way or permit is under the jurisdiction of one Federal agency, the agency head, rather than the Secretary, is authorized to grant or renew the right-of-way or permit for the purposes set forth in this section."],[0,"(2) Where the surface of the Federal lands involved is administered by the Secretary or by two or more Federal agencies, the Secretary is authorized, after consultation with the agencies involved, to grant or renew rights-of-way or permits through the Federal lands involved. The Secretary may enter into interagency agreements with all other Federal agencies having jurisdiction over Federal lands for the purpose of avoiding duplication, assigning responsibility, expediting review of rights-of-way or permit applications, issuing joint regulations, and assuring a decision based upon a comprehensive review of all factors involved in any right-of-way or permit application. Each agency head shall administer and enforce the provisions of this section, appropriate regulations, and the terms and conditions of rights-of-way or permits insofar as they involve Federal lands under the agency head's jurisdiction."],[0,"(d) Width limitations"],[0,"The width of a right-of-way shall not exceed fifty feet plus the ground occupied by the pipeline (that is, the pipe and its related facilities) unless the Secretary or agency head finds, and records the reasons for his finding, that in his judgment a wider right-of-way is necessary for operation and maintenance after construction, or to protect the environment or public safety. Related facilities include but are not limited to valves, pump stations, supporting structures, bridges, monitoring and communication devices, surge and storage tanks, terminals, roads, airstrips and campsites and they need not necessarily be connected or contiguous to the pipe and may be the subjects of separate rights-of-way."],[0,"(e) Temporary permits"],[0,"A right-of-way may be supplemented by such temporary permits for the use of Federal lands in the vicinity of the pipeline as the Secretary or agency head finds are necessary in connection with construction, operation, maintenance, or termination of the pipeline, or to protect the natural environment or public safety."],[0,"(f) Regulatory authority"],[0,"Rights-of-way or permits granted or renewed pursuant to this section shall be subject to regulations promulgated in accord with the provisions of this section and shall be subject to such terms and conditions as the Secretary or agency head may prescribe regarding extent, duration, survey, location, construction, operation, maintenance, use, and termination."],[0,"(g) Pipeline safety"],[0,"The Secretary or agency head shall impose requirements for the operation of the pipeline and related facilities in a manner that will protect the safety of workers and protect the public from sudden ruptures and slow degradation of the pipeline."],[0,"(h) Environmental protection"],[0,"(1) Nothing in this section shall be construed to amend, repeal, modify, or change in any way the requirements of section 102(2)(C) [42 U.S.C. 4332(2)(C)] or any other provision of the National Environmental Policy Act of 1969 [42 U.S.C. 4321 et seq.]."],[0,"(2) The Secretary or agency head, prior to granting a right-of-way or permit pursuant to this section for a new project which may have a significant impact on the environment, shall require the applicant to submit a plan of construction, operation, and rehabilitation for such right-of-way or permit which shall comply with this section. The Secretary or agency head shall issue regulations or impose stipulations which shall include, but shall not be limited to: (A) requirements for restoration, revegetation, and curtailment of erosion of the surface of the land; (B) requirements to insure that activities in connection with the right-of-way or permit will not violate applicable air and water quality standards nor related facility siting standards established by or pursuant to law; (C) requirements designed to control or prevent (i) damage to the environment (including damage to fish and wildlife habitat), (ii) damage to public or private property, and (iii) hazards to public health and safety; and (D) requirements to protect the interests of individuals living in the general area of the right-of-way or permit who rely on the fish, wildlife, and biotic resources of the area for subsistence purposes. Such regulations shall be applicable to every right-of-way or permit granted pursuant to this section, and may be made applicable by the Secretary or agency head to existing rights-of-way or permits, or rights-of-way or permits to be renewed pursuant to this section."],[0,"(i) Disclosure"],[0,"If the applicant is a partnership, corporation, association, or other business entity, the Secretary or agency head shall require the applicant to disclose the identity of the participants in the entity. Such disclosure shall include where applicable (1) the name and address of each partner, (2) the name and address of each shareholder owning 3 per centum or more of the shares, together with the number and percentage of any class of voting shares of the entity which such shareholder is authorized to vote, and (3) the name and address of each affiliate of the entity together with, in the case of an affiliate controlled by the entity, the number of shares and the percentage of any class of voting stock of that affiliate owned, directly or indirectly, by that entity, and, in the case of an affiliate which controls that entity, the number of shares and the percentage of any class of voting stock of that entity owned, directly or indirectly, by the affiliate."],[0,"(j) Technical and financial capability"],[0,"The Secretary or agency head shall grant or renew a right-of-way or permit under this section only when he is satisfied that the applicant has the technical and financial capability to construct, operate, maintain, and terminate the project for which the right-of-way or permit is requested in accordance with the requirements of this section."],[0,"(k) Public hearings"],[0,"The Secretary or agency head by regulation shall establish procedures, including public hearings where appropriate, to give Federal, State, and local government agencies and the public adequate notice and an opportunity to comment upon right-of-way applications filed after the date of enactment of this subsection."],[0,"(l) Reimbursement of costs"],[0,"The applicant for a right-of-way or permit shall reimburse the United States for administrative and other costs incurred in processing the application, and the holder of a right-of-way or permit shall reimburse the United States for the costs incurred in monitoring the construction, operation, maintenance, and termination of any pipeline and related facilities on such right-of-way or permit area and shall pay annually in advance the fair market rental value of the right-of-way or permit, as determined by the Secretary or agency head."],[0,"(m) Bonding"],[0,"Where he deems it appropriate the Secretary or agency head may require a holder of a right-of-way or permit to furnish a bond, or other security, satisfactory to the Secretary or agency head to secure all or any of the obligations imposed by the terms and conditions of the right-of-way or permit or by any rule or regulation of the Secretary or agency head."],[0,"(n) Duration of grant"],[0,"Each right-of-way or permit granted or renewed pursuant to this section shall be limited to a reasonable term in light of all circumstances concerning the project, but in no event more than thirty years. In determining the duration of a right-of-way the Secretary or agency head shall, among other things, take into consideration the cost of the facility, its useful life, and any public purpose it serves. The Secretary or agency head shall renew any right-of-way, in accordance with the provisions of this section, so long as the project is in commercial operation and is operated and maintained in accordance with all of the provisions of this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/30/185?type=usc&year=mostrecent&link-type=html"},"op":17,"head":"§185. Rights-of-way for pipelines through Federal lands","tname":"Mineral Lands and Mining","by":{"0":"5, 6, 6, 6, 6, 6, 6","1":"10, 15, 21, 46, 10, 22, 35, 46","2":"7, 7, 14, 47, 48, 14, 17, 1, 7, 13, 37, 47, 16","3":"2, 2, 12, 13","4":"2, 14"}},{"t":"usc","label":"16 U.S.C. § 1241","url":"https://www.law.cornell.edu/uscode/text/16/1241","subs":["(b)","(a)"],"stext":{"head":"§1241. Congressional statement of policy and declaration of purpose","paras":[[0,"(a) Considerations for determining establishment of trails"],[0,"In order to provide for the ever-increasing outdoor recreation needs of an expanding population and in order to promote the preservation of, public access to, travel within, and enjoyment and appreciation of the open-air, outdoor areas and historic resources of the Nation, trails should be established (i) primarily, near the urban areas of the Nation, and (ii) secondarily, within scenic areas and along historic travel routes of the Nation, which are often more remotely located."],[0,"(b) Initial components"],[0,"The purpose of this chapter is to provide the means for attaining these objectives by instituting a national system of recreation, scenic and historic trails, by designating the Appalachian Trail and the Pacific Crest Trail as the initial components of that system, and by prescribing the methods by which, and standards according to which, additional components may be added to the system."],[0,"(c) Volunteer citizen involvement"],[0,"The Congress recognizes the valuable contributions that volunteers and private, nonprofit trail groups have made to the development and maintenance of the Nation's trails. In recognition of these contributions, it is further the purpose of this chapter to encourage and assist volunteer citizen involvement in the planning, development, maintenance, and management, where appropriate, of trails."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1241?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1241. Congressional statement of policy and declaration of purpose","tname":"Conservation","by":{"0":"6, 6, 36","2":"passim, 25, 35","3":"1"}},{"t":"usc","label":"16 U.S.C. § 1242","url":"https://www.law.cornell.edu/uscode/text/16/1242","subs":["(a)","(a)(2)"],"op":1,"by":{"0":"6","2":"25"}},{"t":"usc","label":"16 U.S.C. § 1243","url":"https://www.law.cornell.edu/uscode/text/16/1243","subs":["(b)(iii)","(b)"],"by":{"0":"27","1":"5, 40","2":"28"}},{"t":"usc","label":"16 U.S.C. § 1244","url":"https://www.law.cornell.edu/uscode/text/16/1244","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(a)(6)","(a)(8)","(a)(9)","(a)(10)","(a)(15)","(a)(21)(C)","(a)(22)(C)","(a)(23)(C)","(a)(24)(C)","(a)(25)(C)","(a)(26)(C)","(a)(28)","(a)(29)","(a)(29)(C)","(d)","(d)(1)","(e)","(b)","(d)(2)","(d)(3)","(a)(7)","(a)(13)","(a)(16)(A)","(a)(18)","(a)(24)"],"stext":{"head":"§1244. National scenic and national historic trails","paras":[[0,"(a) Establishment and designation; administration"],[0,"National scenic and national historic trails shall be authorized and designated only by Act of Congress. There are hereby established the following National Scenic and National Historic Trails:"],[0,"(1) The Appalachian National Scenic Trail, a trail of approximately two thousand miles extending generally along the Appalachian Mountains from Mount Katahdin, Maine, to Springer Mountain, Georgia. Insofar as practicable, the right-of-way for such trail shall comprise the trail depicted on the maps identified as \"Nationwide System of Trails, Proposed Appalachian Trail, NST–AT–101–May 1967\", which shall be on file and available for public inspection in the office of the Director of the National Park Service. Where practicable, such rights-of-way shall include lands protected for it under agreements in effect as of October 2, 1968, to which Federal agencies and States were parties. The Appalachian Trail shall be administered primarily as a footpath by the Secretary of the Interior, in consultation with the Secretary of Agriculture."],[0,"(2) The Pacific Crest National Scenic Trail, a trail of approximately two thousand three hundred fifty miles, extending from the Mexican-California border northward generally along the mountain ranges of the west coast States to the Canadian-Washington border near Lake Ross, following the route as generally depicted on the map, identified as \"Nationwide System of Trails, Proposed Pacific Crest Trail, NST–PC–103–May 1967\" which shall be on file and available for public inspection in the office of the Chief of the Forest Service. The Pacific Crest Trail shall be administered by the Secretary of Agriculture, in consultation with the Secretary of the Interior."],[0,"(3) The Oregon National Historic Trail, a route of approximately two thousand miles extending from near Independence, Missouri, to the vicinity of Portland, Oregon, following a route as depicted on maps identified as \"Primary Route of the Oregon Trail 1841–1848\", in the Department of the Interior's Oregon Trail study report dated April 1977, and which shall be on file and available for public inspection in the office of the Director of the National Park Service. The trail shall be administered by the Secretary of the Interior. No land or interest in land outside the exterior boundaries of any federally administered area may be acquired by the Federal Government for the trail except with the consent of the owner of the land or interest in land. The authority of the Federal Government to acquire fee title under this paragraph shall be limited to an average of not more than ¼ mile on either side of the trail."],[0,"(4) The Mormon Pioneer National Historic Trail, a route of approximately one thousand three hundred miles extending from Nauvoo, Illinois, to Salt Lake City, Utah, following the primary historical route of the Mormon Trail as generally depicted on a map, identified as, \"Mormon Trail Vicinity Map, figure 2\" in the Department of the Interior Mormon Trail study report dated March 1977, and which shall be on file and available for public inspection in the office of the Director, National Park Service, Washington, D.C. The trail shall be administered by the Secretary of the Interior. No land or interest in land outside the exterior boundaries of any federally administered area may be acquired by the Federal Government for the trail except with the consent of the owner of the land or interest in land. The authority of the Federal Government to acquire fee title under this paragraph shall be limited to an average of not more than ¼ mile on either side of the trail."],[0,"(5) The Continental Divide National Scenic Trail, a trail of approximately thirty-one hundred miles, extending from the Montana-Canada border to the New Mexico-Mexico border, following the approximate route depicted on the map, identified as \"Proposed Continental Divide National Scenic Trail\" in the Department of the Interior Continental Divide Trail study report dated March 1977 and which shall be on file and available for public inspection in the office of the Chief, Forest Service, Washington, D.C. The Continental Divide National Scenic Trail shall be administered by the Secretary of Agriculture in consultation with the Secretary of the Interior. Notwithstanding the provisions of section 1246(c) of this title, the use of motorized vehicles on roads which will be designated segments of the Continental Divide National Scenic Trail shall be permitted in accordance with regulations prescribed by the appropriate Secretary. No land or interest in land outside the exterior boundaries of any federally administered area may be acquired by the Federal Government for the trail except with the consent of the owner of the land or interest in land. The authority of the Federal Government to acquire fee title under this paragraph shall be limited to an average of not more than ¼ mile on either side of the trail."],[0,"(6) The Lewis and Clark National Historic Trail, a trail of approximately 4,900 miles, extending from the Ohio River in Pittsburgh, Pennsylvania, to the mouth of the Columbia River in Oregon, following the outbound and inbound routes of the Lewis and Clark Expedition depicted on the map entitled \"Lewis and Clark National Historic Trail Authorized Trail Including Proposed Eastern Legacy Extension\", dated April 2018, and numbered 648/143721. The map shall be on file and available for public inspection in the office of the Director, National Park Service, Washington, D.C. The trail shall be administered by the Secretary of the Interior. No land or interest in land outside the exterior boundaries of any federally administered area may be acquired by the Federal Government for the trail except with the consent of the owner of the land or interest in land. The authority of the Federal Government to acquire fee title under this paragraph shall be limited to an average of not more than ¼ mile on either side of the trail."],[0,"(7) The Iditarod National Historic Trail, a route of approximately two thousand miles extending from Seward, Alaska, to Nome, Alaska, following the routes as depicted on maps identified as \"Seward-Nome Trail\", in the Department of the Interior's study report entitled \"The Iditarod Trail (Seward-Nome Route) and other Alaskan Gold Rush Trails\" dated September 1977. The map shall be on file and available for public inspection in the office of the Director, National Park Service, Washington, D.C. The trail shall be administered by the Secretary of the Interior. No land or interest in land outside the exterior boundaries of any federally administered area may be acquired by the Federal Government for the trail except with the consent of the owner of the land or interest in land. The authority of the Federal Government to acquire fee title under this paragraph shall be limited to an average of not more than ¼ mile on either side of the trail."],[0,"(8) The North Country National Scenic Trail, a trail of approximately 4,600 miles, extending from the Appalachian Trail in Vermont to the vicinity of Lake Sakakawea in North Dakota, following the approximate route depicted on the map identified as \" 'North 1 Country National Scenic Trail, Authorized Route\", dated February 2014, and numbered 649/116870. The map shall be on file and available for public inspection in the office of the Director, National Park Service, Washington, District of Columbia. The trail shall be administered by the Secretary of the Interior. No land or interest in land outside the exterior boundaries of any federally administered area may be acquired by the Federal Government for the trail except with the consent of the owner of the land or interest in land."],[0,"(9) The Overmountain Victory National Historic Trail, a system totaling approximately two hundred seventy-two miles of trail with routes from the mustering point near Abingdon, Virginia, to Sycamore Shoals (near Elizabethton, Tennessee); from Sycamore Shoals to Quaker Meadows (near Morganton, North Carolina); from the mustering point in Surry County, North Carolina, to Quaker Meadows; and from Quaker Meadows to Kings Mountain, South Carolina, as depicted on the map identified as Map 3—Historic Features—1780 in the draft study report entitled \"Overmountain Victory Trail\" dated December 1979. The map shall be on file and available for public inspection in the Office of the Director, National Park Service, Washington, District of Columbia. The trail shall be administered by the Secretary of the Interior."],[0,"(10) The Ice Age National Scenic Trail, a trail of approximately one thousand miles, extending from Door County, Wisconsin, to Interstate Park in Saint Croix County, Wisconsin, generally following the route described in \"On the Trail of the Ice Age—A Hiker's and Biker's Guide to Wisconsin's Ice Age National Scientific Reserve and Trail\", by Henry S. Reuss, Member of Congress, dated 1980. The guide and maps shall be on file and available for public inspection in the Office of the Director, National Park Service, Washington, District of Columbia. Overall administration of the trail shall be the responsibility of the Secretary of the Interior pursuant to subsection (d) of this section. The State of Wisconsin, in consultation with the Secretary of the Interior, may, subject to the approval of the Secretary, prepare a plan for the management of the trail which shall be deemed to meet the requirements of subsection (e) of this section. Notwithstanding the provisions of section 1246(c) of this title, snowmobile use may be permitted on segments of the Ice Age National Scenic Trail where deemed appropriate by the Secretary and the managing authority responsible for the segment. No land or interest in land outside the exterior boundaries of any federally administered area may be acquired by the Federal Government for the trail except with the consent of the owner of the land or interest in land."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1244?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1244. National scenic and national historic trails","tname":"Conservation","by":{"0":"6, 6, 6, 39, 40, 39, 40, 39, 40, 39, 40, 40, 39, 40, 40, 40, 40, 40, 40, 40, 40, 39, 40, 40, 40, 27, 27, 27","1":"5, 8, passim, 25, 7, 25, 26","2":"28, 1, 3, 5, 13, 15, 19, 25, 26, 28, 29, 35, 40, 35, 26, 29, 28, 29, 29, 29, 29, 16, 16, 16","3":"1, 2, 8, 9, 23, 3, 3, 3, 3, 3, 3, 13, 15, 11","4":"5, 7, 9, 21"}},{"t":"usc","label":"16 U.S.C. § 1245","url":"https://www.law.cornell.edu/uscode/text/16/1245","by":{"0":"27"}},{"t":"usc","label":"16 U.S.C. § 1246","url":"https://www.law.cornell.edu/uscode/text/16/1246","subs":["(a)(1)","(a)(1)(A)","(a)(2)","(b)","(c)","(d)","(e)(1970)","(e)","(g)","(h)(1)","(i)","(k)","(a)","(f)","(h)","(a)(1)(B)"],"stext":{"head":"§1246. Administration and development of national trails system","paras":[[0,"(a) Consultation of Secretary with other agencies; transfer of management responsibilities; selection of rights-of-way; criteria for selection; notice; impact upon established uses"],[0,"(1)(A) The Secretary charged with the overall administration of a trail pursuant to section 1244(a) of this title shall, in administering and managing the trail, consult with the heads of all other affected State and Federal agencies. Nothing contained in this chapter shall be deemed to transfer among Federal agencies any management responsibilities established under any other law for federally administered lands which are components of the National Trails System. Any transfer of management responsibilities may be carried out between the Secretary of the Interior and the Secretary of Agriculture only as provided under subparagraph (B)."],[0,"(B) The Secretary charged with the overall administration of any trail pursuant to section 1244(a) of this title may transfer management of any specified trail segment of such trail to the other appropriate Secretary pursuant to a joint memorandum of agreement containing such terms and conditions as the Secretaries consider most appropriate to accomplish the purposes of this chapter. During any period in which management responsibilities for any trail segment are transferred under such an agreement, the management of any such segment shall be subject to the laws, rules, and regulations of the Secretary provided with the management authority under the agreement, except to such extent as the agreement may otherwise expressly provide."],[0,"(2) Pursuant to section 1244(a) of this title, the appropriate Secretary shall select the rights-of-way for national scenic and national historic trails and shall publish notice of the availability of appropriate maps or descriptions in the Federal Register: Provided, That in selecting the rights-of-way full consideration shall be given to minimizing the adverse effects upon the adjacent landowner or user and his operation. Development and management of each segment of the National Trails System shall be designed to harmonize with and complement any established multiple-use plans for that specific area in order to insure continued maximum benefits from the land. The location and width of such rights-of-way across Federal lands under the jurisdiction of another Federal agency shall be by agreement between the head of that agency and the appropriate Secretary. In selecting rights-of-way for trail purposes, the Secretary shall obtain the advice and assistance of the States, local governments, private organizations, and landowners and land users concerned."],[0,"(b) Relocation of segment of national, scenic or historic, trail right-of-way; determination of necessity with official having jurisdiction; necessity for Act of Congress"],[0,"After publication of notice of the availability of appropriate maps or descriptions in the Federal Register, the Secretary charged with the administration of a national scenic or national historic trail may relocate segments of a national scenic or national historic trail right-of-way, with the concurrence of the head of the Federal agency having jurisdiction over the lands involved, upon a determination that: (i) such a relocation is necessary to preserve the purposes for which the trail was established, or (ii) the relocation is necessary to promote a sound land management program in accordance with established multiple-use principles: Provided, That a substantial relocation of the rights-of-way for such trail shall be by Act of Congress."],[0,"(c) Facilities on national, scenic or historic, trails; permissible activities; use of motorized vehicles; trail markers; establishment of uniform marker; placement of uniform markers; trail interpretation sites"],[0,"National scenic or national historic trails may contain campsites, shelters, and related-public-use facilities. Other uses along the trail, which will not substantially interfere with the nature and purposes of the trail, may be permitted by the Secretary charged with the administration of the trail. Reasonable efforts shall be made to provide sufficient access opportunities to such trails and, to the extent practicable, efforts shall be made to avoid activities incompatible with the purposes for which such trails were established. The use of motorized vehicles by the general public along any national scenic trail shall be prohibited and nothing in this chapter shall be construed as authorizing the use of motorized vehicles within the natural and historical areas of the national park system, the national wildlife refuge system, the national wilderness preservation system where they are presently prohibited or on other Federal lands where trails are designated as being closed to such use by the appropriate Secretary: Provided, That the Secretary charged with the administration of such trail shall establish regulations which shall authorize the use of motorized vehicles when, in his judgment, such vehicles are necessary to meet emergencies or to enable adjacent landowners or land users to have reasonable access to their lands or timber rights: Provided further, That private lands included in the national recreation, national scenic, or national historic trails by cooperative agreement of a landowner shall not preclude such owner from using motorized vehicles on or across such trails or adjacent lands from time to time in accordance with regulations to be established by the appropriate Secretary. Where a national historic trail follows existing public roads, developed rights-of-way or waterways, and similar features of man's nonhistorically related development, approximating the original location of a historic route, such segments may be marked to facilitate retracement of the historic route, and where a national historic trail parallels an existing public road, such road may be marked to commemorate the historic route. Other uses along the historic trails and the Continental Divide National Scenic Trail, which will not substantially interfere with the nature and purposes of the trail, and which, at the time of designation, are allowed by administrative regulations, including the use of motorized vehicles, shall be permitted by the Secretary charged with the administration of the trail. The Secretary of the Interior and the Secretary of Agriculture, in consultation with appropriate governmental agencies and public and private organizations, shall establish a uniform marker, including thereon an appropriate and distinctive symbol for each national recreation, national scenic, and national historic trail. Where the trails cross lands administered by Federal agencies such markers shall be erected at appropriate points along the trails and maintained by the Federal agency administering the trail in accordance with standards established by the appropriate Secretary and where the trails cross non-Federal lands, in accordance with written cooperative agreements, the appropriate Secretary shall provide such uniform markers to cooperating agencies and shall require such agencies to erect and maintain them in accordance with the standards established. The appropriate Secretary may also provide for trail interpretation sites, which shall be located at historic sites along the route of any national scenic or national historic trail, in order to present information to the public about the trail, at the lowest possible cost, with emphasis on the portion of the trail passing through the State in which the site is located. Wherever possible, the sites shall be maintained by a State agency under a cooperative agreement between the appropriate Secretary and the State agency."],[0,"(d) Use and acquisition of lands within exterior boundaries of areas included within right-of-way"],[0,"Within the exterior boundaries of areas under their administration that are included in the right-of-way selected for a national recreation, national scenic, or national historic trail, the heads of Federal agencies may use lands for trail purposes and may acquire lands or interests in lands by written cooperative agreement, donation, purchase with donated or appropriated funds or exchange."],[0,"(e) Right-of-way lands outside exterior boundaries of federally administered areas; cooperative agreements or acquisition; failure to agree or acquire; agreement or acquisition by Secretary concerned; right of first refusal for original owner upon disposal"],[0,"Where the lands included in a national scenic or national historic trail right-of-way are outside of the exterior boundaries of federally administered areas, the Secretary charged with the administration of such trail shall encourage the States or local governments involved (1) to enter into written cooperative agreements with landowners, private organizations, and individuals to provide the necessary trail right-of-way, or (2) to acquire such lands or interests therein to be utilized as segments of the national scenic or national historic trail: Provided, That if the State or local governments fail to enter into such written cooperative agreements or to acquire such lands or interests therein after notice of the selection of the right-of-way is published, the appropriate Secretary may (i) enter into such agreements with landowners, States, local governments, private organizations, and individuals for the use of lands for trail purposes, or (ii) acquire private lands or interests therein by donation, purchase with donated or appropriated funds or exchange in accordance with the provisions of subsection (f) of this section: Provided further, That the appropriate Secretary may acquire lands or interests therein from local governments or governmental corporations with the consent of such entities. The lands involved in such rights-of-way should be acquired in fee, if other methods of public control are not sufficient to assure their use for the purpose for which they are acquired: Provided, That if the Secretary charged with the administration of such trail permanently relocates the right-of-way and disposes of all title or interest in the land, the original owner, or his heirs or assigns, shall be offered, by notice given at the former owner's last known address, the right of first refusal at the fair market price."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1246?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§1246. Administration and development of national trails system","tname":"Conservation","by":{"0":"26, 11, 11, 11, 11, 11, 11, 27, 27, 27, 27, 27","1":"passim, 26, 40, 24, 40, 7, 25, 40","2":"25, 35, 37, 35, 26, 27, 26, 29, 27, 35, 48, 26, 38, 25, 26, 26, 27, 35, 27, 35, 40, 42","3":"2, 10, 11, 12, 13, 23, 13, 13, 13, 8, 13, 22, 13, 15, 16","4":"passim"}},{"t":"usc","label":"16 U.S.C. § 1247","url":"https://www.law.cornell.edu/uscode/text/16/1247","subs":["(a)"],"by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 98-11","url":"https://www.govinfo.gov/link/statute/97/45","by":{"0":"12","1":"32","2":"34, 35"}},{"t":"usc","label":"16 U.S.C. § 1271","url":"https://www.law.cornell.edu/uscode/text/16/1271","by":{"0":"22","2":"36, 41, 42, 44","3":"8"}},{"t":"usc","label":"16 U.S.C. § 1274","url":"https://www.law.cornell.edu/uscode/text/16/1274","subs":["(a)","(a)(5)","(b)"],"by":{"0":"23","2":"37","3":"9, 16","4":"10"}},{"t":"usc","label":"16 U.S.C. § 1277","url":"https://www.law.cornell.edu/uscode/text/16/1277","subs":["(e)"],"stext":{"head":"§1277. Land acquisition","paras":[[0,"(a) Grant of authority to acquire; State and Indian lands; use of appropriated funds; acquisition of tracts partially outside component boundaries; disposition of lands"],[0,"(1) The Secretary of the Interior and the Secretary of Agriculture are each authorized to acquire lands and interests in land within the authorized boundaries of any component of the national wild and scenic rivers system designated in section 1274 of this title, or hereafter designated for inclusion in the system by Act of Congress, which is administered by him, but he shall not acquire fee title to an average of more than 100 acres per mile on both sides of the river. Lands owned by a State may be acquired only by donation or by exchange in accordance with subsection (d) of this section. Lands owned by an Indian tribe or a political subdivision of a State may not be acquired without the consent of the appropriate governing body thereof as long as the Indian tribe or political subdivision is following a plan for management and protection of the lands which the Secretary finds protects the land and assures its use for purposes consistent with this chapter. Money appropriated for Federal purposes from the land and water conservation fund shall, without prejudice to the use of appropriations from other sources, be available to Federal departments and agencies for the acquisition of property for the purposes of this chapter."],[0,"(2) When a tract of land lies partially within and partially outside the boundaries of a component of the National Wild and Scenic Rivers System, the appropriate Secretary may, with the consent of the landowners for the portion outside the boundaries, acquire the entire tract. The land or interest therein so acquired outside the boundaries shall not be counted against the average one-hundred-acre-per-mile fee title limitation of subsection (a)(1). The lands or interests therein outside such boundaries, shall be disposed of, consistent with existing authorities of law, by sale, lease, or exchange."],[0,"(b) Curtailment of condemnation power in area 50 per centum or more of which is owned in fee title by Federal or State government"],[0,"If 50 per centum or more of the entire acreage outside the ordinary high water mark on both sides of the river within a federally administered wild, scenic or recreational river area is owned in fee title by the United States, by the State or States within which it lies, or by political subdivisions of those States, neither Secretary shall acquire fee title to any lands by condemnation under authority of this chapter. Nothing contained in this section, however, shall preclude the use of condemnation when necessary to clear title or to acquire scenic easements or such other easements as are reasonably necessary to give the public access to the river and to permit its members to traverse the length of the area or of selected segments thereof."],[0,"(c) Curtailment of condemnation power in urban areas covered by valid and satisfactory zoning ordinances"],[0,"Neither the Secretary of the Interior nor the Secretary of Agriculture may acquire lands by condemnation, for the purpose of including such lands in any national wild, scenic or recreational river area, if such lands are located within any incorporated city, village, or borough which has in force and applicable to such lands a duly adopted, valid zoning ordinance that conforms with the purposes of this chapter. In order to carry out the provisions of this subsection the appropriate Secretary shall issue guidelines, specifying standards for local zoning ordinances, which are consistent with the purposes of this chapter. The standards specified in such guidelines shall have the object of (A) prohibiting new commercial or industrial uses other than commercial or industrial uses which are consistent with the purposes of this chapter, and (B) the protection of the bank lands by means of acreage, frontage, and setback requirements on development."],[0,"(d) Exchange of property"],[0,"The appropriate Secretary is authorized to accept title to non-Federal property within the authorized boundaries of any federally administered component of the national wild and scenic rivers system designated in section 1274 of this title or hereafter designated for inclusion in the system by Act of Congress and, in exchange therefor, convey to the grantor any federally owned property which is under his jurisdiction within the State in which the component lies and which he classifies as suitable for exchange or other disposal. The values of the properties so exchanged either shall be approximately equal or, if they are not approximately equal, shall be equalized by the payment of cash to the grantor or to the Secretary as the circumstances require."],[0,"(e) Transfer of jurisdiction over federally owned property to appropriate Secretary"],[0,"The head of any Federal department or agency having administrative jurisdiction over any lands or interests in land within the authorized boundaries of any federally administered component of the national wild and scenic rivers system designated in section 1274 of this title or hereafter designated for inclusion in the system by Act of Congress is authorized to transfer to the appropriate secretary jurisdiction over such lands for administration in accordance with the provisions of this chapter. Lands acquired by or transferred to the Secretary of Agriculture for the purposes of this chapter within or adjacent to a national forest shall upon such acquisition or transfer become national forest lands."],[0,"(f) Acceptance of donated land, funds, and other property"],[0,"The appropriate Secretary is authorized to accept donations of lands and interests in land, funds, and other property for use in connection with his administration of the national wild and scenic rivers system."],[0,"(g) Retained right of use and occupancy; termination; fair market value; \"improved property\" defined"],[0,"(1) Any owner or owners (hereinafter in this subsection referred to as \"owner\") of improved property on the date of its acquisition, may retain for themselves and their successors or assigns a right of use and occupancy of the improved property for noncommercial residential purposes for a definite term not to exceed twenty-five years or, in lieu thereof, for a term ending at the death of the owner, or the death of his spouse, or the death of either or both of them. The owner shall elect the term to be reserved. The appropriate Secretary shall pay to the owner the fair market value of the property on the date of such acquisition less the fair market value on such date of the right retained by the owner."],[0,"(2) A right of use and occupancy retained pursuant to this subsection shall be subject to termination whenever the appropriate Secretary is given reasonable cause to find that such use and occupancy is being exercised in a manner which conflicts with the purposes of this chapter. In the event of such a finding, the Secretary shall tender to the holder of that right an amount equal to the fair market value of that portion of the right which remains unexpired on the date of termination. Such right of use or occupancy shall terminate by operation of law upon tender of the fair market price."],[0,"(3) The term \"improved property\", as used in this chapter, means a detached, one-family dwelling (hereinafter referred to as \"dwelling\"), the construction of which was begun before January 1, 1967, (except where a different date is specifically provided by law with respect to any particular river) together with so much of the land on which the dwelling is situated, the said land being in the same ownership as the dwelling, as the appropriate Secretary shall designate to be reasonably necessary for the enjoyment of the dwelling for the sole purpose of noncommercial residential use, together with any structures accessory to the dwelling which are situated on the land so designated."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1277?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1277. Land acquisition","tname":"Conservation","by":{"0":"23, 28","1":"28, 8, 28","2":"41, 41","3":"16"}},{"t":"usc","label":"16 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/16/1","subs":["(1970)"],"op":9,"tname":"Conservation","by":{"0":"4"}},{"t":"usc","label":"16 U.S.C. § 1c","url":"https://www.law.cornell.edu/uscode/text/16/1c","subs":["(a)(1970)","(a)","(b)","(a)(1964)","(b)(1964)"],"by":{"0":"3, 21","2":"15, 16","3":"16, 16, 16"}},{"t":"usc","label":"16 U.S.C. § 110c","url":"https://www.law.cornell.edu/uscode/text/16/110c","subs":["(c)(1)"],"by":{"0":"23"}},{"t":"usc","label":"16 U.S.C. § 403h-14","url":"https://www.law.cornell.edu/uscode/text/16/403h-14","by":{"0":"22"}},{"t":"usc","label":"16 U.S.C. § 450ff-5","url":"https://www.law.cornell.edu/uscode/text/16/450ff-5","by":{"0":"24"}},{"t":"usc","label":"16 U.S.C. § 460a-2","url":"https://www.law.cornell.edu/uscode/text/16/460a-2","by":{"0":"38","1":"31","2":"36, 43","3":"10"}},{"t":"usc","label":"16 U.S.C. § 460a-3","url":"https://www.law.cornell.edu/uscode/text/16/460a-3","by":{"0":"38","1":"10, 16, 32","2":"44, 45, 46"}},{"t":"usc","label":"16 U.S.C. § 460a-6","url":"https://www.law.cornell.edu/uscode/text/16/460a-6","by":{"0":"23","2":"43","3":"8, 9"}},{"t":"usc","label":"16 U.S.C. § 460a-8","url":"https://www.law.cornell.edu/uscode/text/16/460a-8","by":{"0":"38","2":"44, 45"}},{"t":"usc","label":"16 U.S.C. § 460l-18","url":"https://www.law.cornell.edu/uscode/text/16/460l-18","subs":["(c)"],"by":{"0":"24","2":"41-42"}},{"t":"usc","label":"16 U.S.C. § 460yy-1","url":"https://www.law.cornell.edu/uscode/text/16/460yy-1","subs":["(d)(2)"],"by":{"0":"23"}},{"t":"usc","label":"16 U.S.C. § 471","url":"https://www.law.cornell.edu/uscode/text/16/471","subs":["(1970)"],"by":{"0":"5"}},{"t":"usc","label":"16 U.S.C. § 528","url":"https://www.law.cornell.edu/uscode/text/16/528","by":{"0":"4","3":"20"}},{"t":"usc","label":"16 U.S.C. § 555a","url":"https://www.law.cornell.edu/uscode/text/16/555a","by":{"0":"22"}},{"t":"usc","label":"16 U.S.C. § 1609","url":"https://www.law.cornell.edu/uscode/text/16/1609","subs":["(a)"],"op":1,"by":{"0":"4","1":"4"}},{"t":"usc","label":"43 U.S.C. § 2632","url":"https://www.law.cornell.edu/uscode/text/43/2632","by":{"0":"24"}},{"t":"usc","label":"54 U.S.C. § 100101","url":"https://www.law.cornell.edu/uscode/text/54/100101","subs":["(a)","(b)(1)(B)","(b)(1)(D)","(b)(2)"],"stext":{"head":"§100101. Promotion and regulation","paras":[[0,"(a) In General.—The Secretary, acting through the Director of the National Park Service, shall promote and regulate the use of the National Park System by means and measures that conform to the fundamental purpose of the System units, which purpose is to conserve the scenery, natural and historic objects, and wild life in the System units and to provide for the enjoyment of the scenery, natural and historic objects, and wild life in such manner and by such means as will leave them unimpaired for the enjoyment of future generations."],[0,"(b) Declarations.—"],[1,"(1) 1970 declarations.—Congress declares that—"],[2,"(A) the National Park System, which began with establishment of Yellowstone National Park in 1872, has since grown to include superlative natural, historic, and recreation areas in every major region of the United States and its territories and possessions;"],[2,"(B) these areas, though distinct in character, are united through their interrelated purposes and resources into one National Park System as cumulative expressions of a single national heritage;"],[2,"(C) individually and collectively, these areas derive increased national dignity and recognition of their superb environmental quality through their inclusion jointly with each other in one System preserved and managed for the benefit and inspiration of all the people of the United States; and"],[2,"(D) it is the purpose of this division to include all these areas in the System and to clarify the authorities applicable to the System."],[1,"(2) 1978 reaffirmation.—Congress reaffirms, declares, and directs that the promotion and regulation of the various System units shall be consistent with and founded in the purpose established by subsection (a), to the common benefit of all the people of the United States. The authorization of activities shall be construed and the protection, management, and administration of the System units shall be conducted in light of the high public value and integrity of the System and shall not be exercised in derogation of the values and purposes for which the System units have been established, except as directly and specifically provided by Congress."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/54/100101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§100101. Promotion and regulation","tname":"National Park Service and Related Programs","by":{"0":"4","1":"4","2":"passim, 3, 6, 6, 16, 6, 16, 6, 16, 16, 16, 16","3":"14, 21"}},{"t":"usc","label":"54 U.S.C. § 100102","url":"https://www.law.cornell.edu/uscode/text/54/100102","subs":["(2)","(6)"],"stext":{"head":"§100102. Definitions","paras":[[0,"In this title:"],[1,"(1) Director.—The term \"Director\" means the Director of the National Park Service."],[1,"(2) National park system.—The term \"National Park System\" means the areas of land and water described in section 100501 of this title."],[1,"(3) Secretary.—The term \"Secretary\" means the Secretary of the Interior."],[1,"(4) Service.—The term \"Service\" means the National Park Service."],[1,"(5) System.—The term \"System\" means the National Park System."],[1,"(6) System unit.—The term \"System unit\" means one of the areas described in section 100501 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/54/100102?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§100102. Definitions","tname":"National Park Service and Related Programs","by":{"0":"6, 6","1":"38","2":"14, 2, 6, 30, 16","3":"2, 12, 16, 17, 18"}},{"t":"usc","label":"54 U.S.C. § 100501","url":"https://www.law.cornell.edu/uscode/text/54/100501","stext":{"head":"§100501. Areas included in System","paras":[[0,"The System shall include any area of land and water administered by the Secretary, acting through the Director, for park, monument, historic, parkway, recreational, or other purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/54/100501?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§100501. Areas included in System","tname":"National Park Service and Related Programs","by":{"0":"6","1":"38","2":"1, 2, 5, 13, 14, 16, 30, 35, 16, 16","3":"2, 12, 16, 17, 18"}},{"t":"reg","label":"36 Fed. Reg. 2676","url":"https://www.govinfo.gov/link/fr/36/2676","by":{"0":"10, 31"}},{"t":"reg","label":"36 Fed. Reg. 19,802","url":"https://www.govinfo.gov/link/fr/36/19802","by":{"0":"10"}},{"t":"case","label":"Defs. of Wildlife v. U.S. Dept. of the Int.","cite":"931 F.3d 339","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/931/339/","by":{"1":"17"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Sierra Club v. U.S. Army Corps of Eng’rs","cite":"909 F.3d 635","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/909/635/","by":{"1":"17"}},{"t":"case","label":"Sierra Club v. U.S. Forest Serv.","cite":"828 F.3d 402","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/828/402/","by":{"1":"48","4":"23"}},{"t":"case","label":"Sierra Club, Inc. v. U.S. Forest Serv.","cite":"897 F.3d 582","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/897/582/","by":{"1":"17"}},{"t":"case","label":"Steel Co. v. Citizens for Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"United States v. Grimaud","cite":"220 U.S. 506","y":1911,"id":"scdb/1910-122","sc":1,"sum":"Under the acts establishing forest reservations, their use for grazing or other lawful purposes is subject to rules and regulations established by the Secretary of Agriculture, and it being impracticable for Congress to provide general regulations, that body acted within its constitutional power in conferring power on the Secretary to establish such rules; the power so conferred being administrative and not …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"W. Va. U. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"usc","label":"16 U.S.C. § 460a-7","url":"https://www.law.cornell.edu/uscode/text/16/460a-7","subs":["(3)"],"by":{"1":"31","2":"29"}},{"t":"usc","label":"16 U.S.C. § 1281","url":"https://www.law.cornell.edu/uscode/text/16/1281","subs":["(c)"],"stext":{"head":"§1281. Administration","paras":[[0,"(a) Public use and enjoyment of components; protection of features; management plans"],[0,"Each component of the national wild and scenic rivers system shall be administered in such manner as to protect and enhance the values which caused it to be included in said system without, insofar as is consistent therewith, limiting other uses that do not substantially interfere with public use and enjoyment of these values. In such administration primary emphasis shall be given to protecting its esthetic, scenic, historic, archeologic, and scientific features. Management plans for any such component may establish varying degrees of intensity for its protection and development, based on the special attributes of the area."],[0,"(b) Wilderness areas"],[0,"Any portion of a component of the national wild and scenic rivers system that is within the national wilderness preservation system, as established by or pursuant to the Wilderness Act [16 U.S.C. 1131 et seq.], shall be subject to the provisions of both the Wilderness Act and this chapter with respect to preservation of such river and its immediate environment, and in case of conflict between the provisions of the Wilderness Act and this chapter the more restrictive provisions shall apply."],[0,"(c) Areas administered by National Park Service and Fish and Wildlife Service"],[0,"Any component of the national wild and scenic rivers system that is administered by the Secretary of the Interior through the National Park Service shall become a part of the national park system, and any such component that is administered by the Secretary through the Fish and Wildlife Service shall become a part of the national wildlife refuge system. The lands involved shall be subject to the provisions of this chapter and the Acts under which the national park system or national wildlife system, as the case may be, is administered, and in case of conflict between the provisions of this chapter and such Acts, the more restrictive provisions shall apply. The Secretary of the Interior, in his administration of any component of the national wild and scenic rivers system, may utilize such general statutory authorities relating to areas of the national park system and such general statutory authorities otherwise available to him for recreation and preservation purposes and for the conservation and management of natural resources as he deems appropriate to carry out the purposes of this chapter."],[0,"(d) Statutory authorities relating to national forests"],[0,"The Secretary of Agriculture, in his administration of any component of the national wild and scenic rivers system area, may utilize the general statutory authorities relating to the national forests in such manner as he deems appropriate to carry out the purposes of this chapter."],[0,"(e) Cooperative agreements with State and local governments"],[0,"The Federal agency charged with the administration of any component of the national wild and scenic rivers system may enter into written cooperative agreements with the Governor of a State, the head of any State agency, or the appropriate official of a political subdivision of a State for State or local governmental participation in the administration of the component. The States and their political subdivisions shall be encouraged to cooperate in the planning and administration of components of the system which include or adjoin State- or county-owned lands."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1281?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1281. Administration","tname":"Conservation","by":{"1":"8, 28","2":"36, 41, 42","3":"16","4":"10"}},{"t":"usc","label":"16 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/16/1604","subs":["(i)"],"op":1,"by":{"1":"14","2":"12"}},{"t":"usc","label":"42 U.S.C. § 4321","url":"https://www.law.cornell.edu/uscode/text/42/4321","op":1,"by":{"1":"14"}},{"t":"usc","label":"42 U.S.C. § 4370m","url":"https://www.law.cornell.edu/uscode/text/42/4370m","subs":["(6)"],"by":{"1":"47"}},{"t":"usc","label":"5 U.S.C. § 500","url":"https://www.law.cornell.edu/uscode/text/5/500","op":1,"by":{"1":"14"}},{"t":"usc","label":"54 U.S.C. § 101102","url":"https://www.law.cornell.edu/uscode/text/54/101102","subs":["(a)"],"by":{"1":"37"}},{"t":"usc","label":"54 U.S.C. § 102901","url":"https://www.law.cornell.edu/uscode/text/54/102901","subs":["(b)"],"by":{"1":"37"}},{"t":"usc","label":"54 U.S.C. § 200306","url":"https://www.law.cornell.edu/uscode/text/54/200306","subs":["(a)"],"by":{"1":"37"}},{"t":"law","label":"Pub. L. No. 114-94","url":"https://www.govinfo.gov/link/plaw/114/public/94","by":{"1":"47"}},{"t":"law","label":"Pub. L. No. 82-336","url":"https://www.govinfo.gov/link/statute/66/69","by":{"1":"28, 29","4":"11"}},{"t":"law","label":"Pub. L. No. 88-415","url":"https://www.govinfo.gov/link/statute/78/388","by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 89-72","url":"https://www.govinfo.gov/link/statute/79/213","by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 90-542","url":"https://www.govinfo.gov/link/statute/82/906","by":{"1":"8"}},{"t":"law","label":"Pub. L. No. 90-543","url":"https://www.govinfo.gov/link/statute/82/919","by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 90-555","url":"https://www.govinfo.gov/link/statute/82/967","by":{"1":"30","2":"43","4":"11, 13"}},{"t":"reg","label":"48 Fed. Reg. 30,252","url":"https://www.govinfo.gov/link/fr/48/30252","by":{"1":"9, 34"}},{"t":"reg","label":"81 Fed. Reg. 71,041","url":"https://www.govinfo.gov/link/fr/81/71041","by":{"1":"48"}},{"t":"case","label":"Caminetti v. United States","cite":"242 U.S. 470","y":1917,"id":"scdb/1916-190","sc":1,"sum":"The White Slave Traffic Act of June 25, 1910, c. 395, 36 Stat. 825, applies to any case in which a woman is transported in interstate commerce for the purpose of prostitution or concubinage; pecuniary gain, either as a motive for the transportation or as an attendant of its object, is not an element in the offenses defined.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"ICC v. New York, N.H. & H.R.R. Co.","cite":"287 U.S. 178","y":1932,"id":"scdb/1932-042","sc":1,"sum":"That whether the trackage and terminal rights are to be classed as licenses or as easements, the duty to value them specifically, if ib exists under the statute, is not so clearly and certainly imposed as to be enforceable by mandamus. Pp. 191, et seq. Argument for Respondents.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"op":2,"ar":3,"sum":"Alaska’s Nation River is not public land; and like all non-public lands and navigable waters within Alaska’s national parks, it is exempt under the Alaska National Interest Lands Conservation Act from the National Park Service’s ordinary regulatory authority.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"21, 37, 47"}},{"t":"case","label":"Territory of New Mexico v. United States Tr. Co. of New York","cite":"172 U.S. 171","y":1898,"id":"scdb/1898-025","sc":1,"op":3,"sum":"The provision in Sec. 2 of the act of July 27, 1866, c. 278, 14 Stat. 292, 294, which exempts from taxation within the Territories of the United States, the right of way granted by the act to the Atlantic & Pacific Railroad Company, operates to exempt from such taxation the land itself to the extent to which it is made by the act subject to such right of way and all structures erected thereon.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"26","3":"5"}},{"t":"case","label":"United States v. Beasley","cite":"12 F.3d 280","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/12/280/","by":{"2":"42"}},{"t":"case","label":"United States v. Union Pac. R.R. Co.","cite":"353 U.S. 112","y":1957,"id":"1956/97","sc":1,"sum":"The grant by § 2 of the \"right of way\" through the public lands did not convey to the railroad company the title to oil and gas deposits underlying the right of way, and the railroad company may not remove or dispose of such deposits.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"United States v. Ron Pair Enters., Inc.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"46"}},{"t":"case","label":"Wallis v. Pan Am. Petroleum Corp.","cite":"384 U.S. 63","y":1966,"id":"1965/341","sc":1,"op":1,"sum":"State law, which generally controls the dealings of private parties in an oil and gas lease validly issued under the Mineral Leasing Act of 1920, governs the controversy in this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"law","label":"Pub. L. No. 92-589","url":"https://www.govinfo.gov/link/statute/86/1299","by":{"2":"30-31"}},{"t":"law","label":"Pub. L. No. 101-337","url":"https://www.govinfo.gov/link/statute/104/379","by":{"2":"31"}},{"t":"law","label":"Pub. L. No. 113-287","url":"https://www.govinfo.gov/link/plaw/113/public/287","by":{"2":"30"}},{"t":"law","label":"Pub. L. No. 113-291","url":"https://www.govinfo.gov/link/plaw/113/public/291","by":{"2":"31"}},{"t":"usc","label":"16 U.S.C. § 460a-1","url":"https://www.law.cornell.edu/uscode/text/16/460a-1","by":{"2":"29, 43, 44"}},{"t":"law","label":"Pub. L. No. 91-383","url":"https://www.govinfo.gov/link/statute/84/825","by":{"2":"passim"}},{"t":"law","label":"John D. Dingell, Jr. Conservation, Management, and Recreation Act, Pub. L. No. 116-9","url":"https://www.govinfo.gov/link/plaw/116/public/9","by":{"2":"31"}},{"t":"usc","label":"42 U.S.C. § 4331","url":"https://www.law.cornell.edu/uscode/text/42/4331","by":{"2":"12"}},{"t":"usc","label":"42 U.S.C. § 4332","url":"https://www.law.cornell.edu/uscode/text/42/4332","subs":["(C)(iii)"],"by":{"2":"12"}},{"t":"law","label":"Pub. L. No. 94-588","url":"https://www.govinfo.gov/link/statute/90/2949","by":{"2":"12"}},{"t":"usc","label":"54 U.S.C. § 100502","url":"https://www.law.cornell.edu/uscode/text/54/100502","op":1,"by":{"2":"35"}},{"t":"usc","label":"54 U.S.C. § 100507","url":"https://www.law.cornell.edu/uscode/text/54/100507","subs":["(c)(4)(B)"],"by":{"2":"35"}},{"t":"usc","label":"54 U.S.C. § 100706","url":"https://www.law.cornell.edu/uscode/text/54/100706","by":{"2":"35"}},{"t":"usc","label":"54 U.S.C. § 100731","url":"https://www.law.cornell.edu/uscode/text/54/100731","subs":["(1)"],"by":{"2":"18"}},{"t":"usc","label":"54 U.S.C. § 100902","url":"https://www.law.cornell.edu/uscode/text/54/100902","subs":["(a)(1)"],"by":{"2":"16, 46, 7"}},{"t":"usc","label":"16 U.S.C. § 1248","url":"https://www.law.cornell.edu/uscode/text/16/1248","subs":["(a)","(e)(1)"],"stext":{"head":"§1248. Easements and rights-of-way","paras":[[0,"(a) Authorization; conditions"],[0,"The Secretary of the Interior or the Secretary of Agriculture as the case may be, may grant easements and rights-of-way upon, over, under, across, or along any component of the national trails system in accordance with the laws applicable to the national park system and the national forest system, respectively: Provided, That any conditions contained in such easements and rights-of-way shall be related to the policy and purposes of this chapter."],[0,"(b) Cooperation of Federal agencies with Secretary of the Interior and Secretary of Agriculture"],[0,"The Department of Defense, the Department of Transportation, the Surface Transportation Board, the Federal Communications Commission, the Secretary of Energy, and other Federal agencies having jurisdiction or control over or information concerning the use, abandonment, or disposition of roadways, utility rights-of-way, or other properties which may be suitable for the purpose of improving or expanding the national trails system shall cooperate with the Secretary of the Interior and the Secretary of Agriculture in order to assure, to the extent practicable, that any such properties having values suitable for trail purposes may be made available for such use."],[0,"(c) Abandoned railroad grants; retention of rights"],[0,"Commencing October 4, 1988, any and all right, title, interest, and estate of the United States in all rights-of-way of the type described in section 912 of title 43, shall remain in the United States upon the abandonment or forfeiture of such rights-of-way, or portions thereof, except to the extent that any such right-of-way, or portion thereof, is embraced within a public highway no later than one year after a determination of abandonment or forfeiture, as provided under such section."],[0,"(d) Location, incorporation, and management"],[0,"(1) All rights-of-way, or portions thereof, retained by the United States pursuant to subsection (c) which are located within the boundaries of a conservation system unit or a National Forest shall be added to and incorporated within such unit or National Forest and managed in accordance with applicable provisions of law, including this chapter."],[0,"(2) All such retained rights-of-way, or portions thereof, which are located outside the boundaries of a conservation system unit or a National Forest but adjacent to or contiguous with any portion of the public lands shall be managed pursuant to the Federal Land Policy and Management Act of 1976 [43 U.S.C. 1701 et seq.] and other applicable law, including this section."],[0,"(3) All such retained rights-of-way, or portions thereof, which are located outside the boundaries of a conservation system unit or National Forest which the Secretary of the Interior determines suitable for use as a public recreational trail or other recreational purposes shall be managed by the Secretary for such uses, as well as for such other uses as the Secretary determines to be appropriate pursuant to applicable laws, as long as such uses do not preclude trail use."],[0,"(e) Release and quitclaim; conditions; sale; proceeds"],[0,"(1) The Secretary of the Interior is authorized where appropriate to release and quitclaim to a unit of government or to another entity meeting the requirements of this subsection any and all right, title, and interest in the surface estate of any portion of any right-of-way to the extent any such right, title, and interest was retained by the United States pursuant to subsection (c), if such portion is not located within the boundaries of any conservation system unit or National Forest. Such release and quitclaim shall be made only in response to an application therefor by a unit of State or local government or another entity which the Secretary of the Interior determines to be legally and financially qualified to manage the relevant portion for public recreational purposes. Upon receipt of such an application, the Secretary shall publish a notice concerning such application in a newspaper of general circulation in the area where the relevant portion is located. Such release and quitclaim shall be on the following conditions:"],[1,"(A) If such unit or entity attempts to sell, convey, or otherwise transfer such right, title, or interest or attempts to permit the use of any part of such portion for any purpose incompatible with its use for public recreation, then any and all right, title, and interest released and quitclaimed by the Secretary pursuant to this subsection shall revert to the United States."],[1,"(B) Such unit or entity shall assume full responsibility and hold the United States harmless for any legal liability which might arise with respect to the transfer, possession, use, release, or quitclaim of such right-of-way."],[1,"(C) Notwithstanding any other provision of law, the United States shall be under no duty to inspect such portion prior to such release and quitclaim, and shall incur no legal liability with respect to any hazard or any unsafe condition existing on such portion at the time of such release and quitclaim."],[0,"(2) The Secretary is authorized to sell any portion of a right-of-way retained by the United States pursuant to subsection (c) located outside the boundaries of a conservation system unit or National Forest if any such portion is—"],[1,"(A) not adjacent to or contiguous with any portion of the public lands; or"],[1,"(B) determined by the Secretary, pursuant to the disposal criteria established by section 203 of the Federal Land Policy and Management Act of 1976 [43 U.S.C. 1713], to be suitable for sale."],[0,"Prior to conducting any such sale, the Secretary shall take appropriate steps to afford a unit of State or local government or any other entity an opportunity to seek to obtain such portion pursuant to paragraph (1) of this subsection."],[0,"(3) All proceeds from sales of such retained rights of way shall be deposited into the Treasury of the United States and credited to the Land and Water Conservation Fund as provided in section 200302 of title 54."],[0,"(4) The Secretary of the Interior shall annually report to the Congress the total proceeds from sales under paragraph (2) during the preceding fiscal year. Such report shall be included in the President's annual budget submitted to the Congress."],[0,"(f) \"Conservation system unit\" and \"public lands\" defined"],[0,"As used in this section—"],[1,"(1) The term \"conservation system unit\" has the same meaning given such term in the Alaska National Interest Lands Conservation Act (Public Law 96–487; 94 Stat. 2371 et seq.), except that such term shall also include units outside Alaska."],[1,"(2) The term \"public lands\" has the same meaning given such term in the Federal Land Policy and Management Act of 1976 [43 U.S.C. 1701 et seq.]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1248?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1248. Easements and rights-of-way","tname":"Conservation","by":{"2":"7, 28, 43, 26","3":"6"}},{"t":"usc","label":"16 U.S.C. § 1250","url":"https://www.law.cornell.edu/uscode/text/16/1250","by":{"2":"35"}},{"t":"law","label":"Pub. L. No. 102-562","url":"https://www.govinfo.gov/link/statute/106/4234","by":{"2":"33","3":"20"}},{"t":"usc","label":"16 U.S.C. § 519a","url":"https://www.law.cornell.edu/uscode/text/16/519a","by":{"2":"39"}},{"t":"usc","label":"16 U.S.C. § 521c-521i","url":"https://www.law.cornell.edu/uscode/text/16/521c-521i","by":{"2":"39"}},{"t":"usc","label":"16 U.S.C. § 521i","url":"https://www.law.cornell.edu/uscode/text/16/521i","by":{"2":"39"}},{"t":"usc","label":"16 U.S.C. § 1284","url":"https://www.law.cornell.edu/uscode/text/16/1284","subs":["(g)"],"by":{"2":"43"}},{"t":"usc","label":"16 U.S.C. § 5","url":"https://www.law.cornell.edu/uscode/text/16/5","op":2,"tname":"Conservation","by":{"2":"16, 46"}},{"t":"usc","label":"16 U.S.C. § 19jj","url":"https://www.law.cornell.edu/uscode/text/16/19jj","subs":["(d)","(d)(2000)"],"by":{"2":"31","3":"19"}},{"t":"usc","label":"16 U.S.C. § 79","url":"https://www.law.cornell.edu/uscode/text/16/79","by":{"2":"46"}},{"t":"usc","label":"16 U.S.C. § 410qq-2","url":"https://www.law.cornell.edu/uscode/text/16/410qq-2","by":{"2":"33"}},{"t":"usc","label":"16 U.S.C. § 410bbb","url":"https://www.law.cornell.edu/uscode/text/16/410bbb","by":{"2":"33"}},{"t":"usc","label":"16 U.S.C. § 410uuu","url":"https://www.law.cornell.edu/uscode/text/16/410uuu","subs":["(d)(1)"],"by":{"2":"33","3":"20, 20, 20"}},{"t":"usc","label":"30 U.S.C. § 1272","url":"https://www.law.cornell.edu/uscode/text/30/1272","subs":["(e)(1)"],"by":{"2":"18"}},{"t":"reg","label":"U.S. Dep’t of Interior:, 34 Fed. Reg. 14,337","url":"https://www.govinfo.gov/link/fr/34/14337","by":{"2":"5, 15, 30, 16"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Northern Pac. Ry. Co. v. Townsend","cite":"190 U.S. 267","y":1903,"id":"scdb/1902-190","sc":1,"sum":"Where the United States grants a right of way by statute to a railroad company which files a map of definite location, and the road is constructed, the land forming the right of'way is taken out of the category of public land subject to preemption and sale, and the land department is without authority to convey rights therein. Homesteaders filing entries thereafter can acquire no interest in land within the right of …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"14"}},{"t":"case","label":"United States v. 13.10 Acres of Land","cite":"737 F. Supp. 212","y":1990,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./737/212/","op":1,"by":{"3":"4"}},{"t":"law","label":"Pub. L. No. 111-84","url":"https://www.govinfo.gov/link/plaw/111/public/84","by":{"3":"20"}},{"t":"usc","label":"16 U.S.C. § 1249","url":"https://www.law.cornell.edu/uscode/text/16/1249","subs":["(a)(1)"],"by":{"3":"6"}},{"t":"usc","label":"16 U.S.C. § 19jj-1","url":"https://www.law.cornell.edu/uscode/text/16/19jj-1","subs":["(a)(2000)"],"by":{"3":"19"}},{"t":"usc","label":"16 U.S.C. § 475","url":"https://www.law.cornell.edu/uscode/text/16/475","by":{"3":"20"}},{"t":"case","label":"Great N. Ry. Co. v. United States","cite":"315 U.S. 262","y":1942,"id":"scdb/1941-044","sc":1,"sum":"1. The Right of Way Act of March 3, 1875, granting to railroads the right of way through public lands of the United States, grants an easement only, not a fee, and confers no right to oil and minerals underlying the right of way. Pp. 271, 279.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"6"}},{"t":"case","label":"Marvin M. Brandt Revocable Tr. v. United States","cite":"572 U.S. 93","y":2014,"id":"2013/12-1173","sc":1,"op":1,"sum":"The Court held that the General Railroad Right-of-Way Act of 1875 guaranteed the federal government easements for federally-granted railroad land, but not an enduring property interest.","sumSrc":"Oyez","by":{"4":"6"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"sum":"The Court held that \"holder\" class actions such as Dabit's are \"in connection with the purchase or sale\" of a security and therefore are pre-empted by SLUSA.","sumSrc":"Oyez","by":{"4":"7"}},{"t":"usc","label":"16 U.S.C. § 460","url":"https://www.law.cornell.edu/uscode/text/16/460","by":{"4":"11, 12, 13, 14"}},{"t":"usc","label":"16 U.S.C. § 1280","url":"https://www.law.cornell.edu/uscode/text/16/1280","ar":1,"by":{"4":"10"}},{"t":"usc","label":"54 U.S.C. § 100801","url":"https://www.law.cornell.edu/uscode/text/54/100801","by":{"4":"19"}}]};